SINA_SMART["parasito-candidiasis"] = {"lecture":"parasito-candidiasis","title":"Candidiasis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-candidiasis:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"parasito-candidiasis:e0","text":"Candida albicans: budding yeast, commensal, opportunistic.","topic":"The yeast and contributing factors","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e1","text":"Risk: antibiotics, steroids, diabetes, HIV, catheters, moisture, dentures.","topic":"The yeast and contributing factors","sec":1,"importance":"core","highYield":"foundational"},{"id":"parasito-candidiasis:e2","text":"Oral thrush (CD4 < 300); oesophageal candidiasis (CD4 < 100).","topic":"Superficial candidiasis","sec":2,"importance":"core","highYield":"historically-high-yield"},{"id":"parasito-candidiasis:e3","text":"Vulvovaginal: 75% of women; curd-like white discharge; pregnancy.","topic":"Superficial candidiasis","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e4","text":"Intertrigo: glazed erythema with satellite pustules.","topic":"Superficial candidiasis","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e5","text":"Nail: perionyxis first, fingers of dominant hand.","topic":"Superficial candidiasis","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e6","text":"Invasive: fever > 96 h despite antibiotics in high-risk host.","topic":"Systemic candidiasis","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e10","text":"Mannan antigen + antibodies suggest invasive candidiasis.","topic":"Laboratory diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e7","text":"Direct exam: abundance matters on mucosal samples.","topic":"Laboratory diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e8","text":"Culture: Sabouraud-chloramphenicol; chromogenic media.","topic":"Laboratory diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e9","text":"Germ-tube test (3 h serum, 37 °C) identifies C. albicans.","topic":"Laboratory diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-candidiasis:e11","text":"Local treatment for skin/mouth; fluconazole; echinocandins or amphotericin for invasive.","topic":"Treatment","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1a80k3e":"a","1u97qn5":"a","eqlb9p":"a","rxt08m":"a","14ra64e":"a","12k0ot2":"a","71nkdp":"a","qtc8rh":"a","1ay4gth":"a","wzwp7f":"a","1fb8zhd":"a","87p32q":"a","1ofkfcy":"a","128u2ja":"a","jdq83m":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-candidiasis:s0":{"s":0,"u":["Candidiases are cosmopolitan infections due to yeasts of the genus Candida , arising when local or general immunity fails.","They range from superficial mucocutaneous forms to deep or disseminated candidiasis, which remains serious despite modern antifungals."],"dp":[]},"parasito-candidiasis:e0":{"s":1,"u":["Candida albicans: budding yeast, commensal, opportunistic.","Candida : budding yeasts, non-capsulated , non-pigmented, some forming pseudohyphae or true hyphae.","C. albicans is the main pathogen and a normal commensal of the gut and natural cavities; others: C. glabrata, C. tropicalis, C. krusei, C. parapsilosis, C. dubliniensis, C. auris ."],"dp":[]},"parasito-candidiasis:e1":{"s":1,"u":["Risk: antibiotics, steroids, diabetes, HIV, catheters, moisture, dentures.","Host factors : newborns, elderly (dentures), pregnancy; sweat, maceration, moisture, contact with sugar (pastry cooks), trauma; diabetes , neutropenia, cancer, HIV .","Iatrogenic : antibiotics , corticosteroids, antiseptics, immunosuppressants, contraceptive hormones, radiotherapy, IV drug use, digestive or cardiac surgery, transplantation, IV catheters and parenteral nutrition , burns, urinary catheters, prostheses."],"dp":[]},"parasito-candidiasis:e2":{"s":2,"u":["Oral thrush (CD4 < 300); oesophageal candidiasis (CD4 < 100).","Oesophageal : with oral candidiasis, common in HIV with CD4 , cancer, leukaemia; dysphagia, retrosternal burning; endoscopy shows white-yellow plaques; biopsy.","Oral : commensal becomes pathogen when flora is disturbed; risk factors: dentures, dry mouth (xerostomia), psychotropic drugs, inhaled steroids, antibiotics, chemo/radiotherapy, pregnancy, poorly controlled diabetes, undernutrition, HIV ( CD4 ); thrush (pseudomembranous white plaques), heals without sequelae."],"dp":[]},"parasito-candidiasis:e3":{"s":2,"u":["Vulvovaginal: 75% of women; curd-like white discharge; pregnancy.","Vulvovaginal : C. albicans 80%, C. glabrata 10%; 75% of women have one episode; pregnancy triggers; itch, burning, dyspareunia, dysuria, red swollen vulva, curd-like white discharge ; balanitis in men."],"dp":[]},"parasito-candidiasis:e4":{"s":2,"u":["Intertrigo: glazed erythema with satellite pustules.","Skin : intertrigo of large folds (groin, abdomen, submammary, axillary, intergluteal) or small folds (lip commissures, finger webs): glazed, oozing erythema starting at the fold bottom with a white coating and satellite papulo-pustules ; napkin candidiasis in infants."],"dp":[]},"parasito-candidiasis:e5":{"s":2,"u":["Nail: perionyxis first, fingers of dominant hand.","Nails : fingernails (3rd finger, dominant hand), favoured by water, sugar, manicure, diabetes; begins with painful perionyxis (pus on pressure) then onyxis."],"dp":[]},"parasito-candidiasis:e6":{"s":3,"u":["Invasive: fever > 96 h despite antibiotics in high-risk host.","Classified as proven (yeast on histology of a non-mucosal biopsy, or culture from a sterile site with compatible findings), probable or possible using host criteria (neutropenia 10 days, fever > 96 h despite broad-spectrum antibiotics , recent immunosuppressants or steroids > 3 weeks, AIDS), microbiological and clinical criteria (e.g. chorioretinitis)."],"dp":[]},"parasito-candidiasis:e10":{"s":4,"u":["Mannan antigen + antibodies suggest invasive candidiasis.","Serology : anti-Candida antibodies; mannan antigen and β-1,3-glucan ; combined antigen + antibody suggests invasive candidiasis; follow-up is essential."],"dp":[]},"parasito-candidiasis:e7":{"s":4,"u":["Direct exam: abundance matters on mucosal samples.","Direct exam (essential, rapid): budding elements 1-10 µm, thin-walled, uncapsulated, ± filaments; in stool, sputum and mucosa only abnormal abundance means more than commensalism; count urine yeasts."],"dp":[{"h":"Why a positive culture is not always infection","t":"Candida albicans lives normally on mucosae and in stool, so finding it proves little by itself. What matters is abundance on direct examination, the site (a sterile site such as blood or CSF is always significant), and the clinical picture. That is why the lecture stresses direct examination and antigen testing alongside culture. Source: the lecture's direct examination slide."}]},"parasito-candidiasis:e8":{"s":4,"u":["Culture: Sabouraud-chloramphenicol; chromogenic media.","Culture : Sabouraud-chloramphenicol (± actidione) at 25-37 °C for 3 days (1 week for deep samples); chromogenic media identify C. albicans directly."],"dp":[]},"parasito-candidiasis:e9":{"s":4,"u":["Germ-tube test (3 h serum, 37 °C) identifies C. albicans.","Identification of C. albicans : germ-tube (blastesis) test in serum at 37 °C for 3 h , latex agglutination (5 min), chlamydospores on RAT/PCB agar; other species by sugar assimilation (auxanogram) and fermentation, urease."],"dp":[]},"parasito-candidiasis:e11":{"s":5,"u":["Local treatment for skin/mouth; fluconazole; echinocandins or amphotericin for invasive.","Disseminated : IV amphotericin B or lipid forms, fluconazole (IV then oral), voriconazole, echinocandins .","Oral : local amphotericin B suspension or mouthwash (15-21 days), nystatin, miconazole gel or mucoadhesive tablet; fluconazole 50 mg/day for 1-2 weeks if recurrent; treat the cause (dry mouth, clean and soak dentures)."],"dp":[]}},"meta":{"1a80k3e":{"a":"recall","vg":"parasito-candidiasis:e0/recall/1"},"1u97qn5":{"a":"recall","vg":"parasito-candidiasis:e0/recall/2"},"eqlb9p":{"a":"recall","vg":"parasito-candidiasis:e6/recall/1"},"rxt08m":{"a":"recall","vg":"parasito-candidiasis:e2/recall/1"},"14ra64e":{"a":"recall","vg":"parasito-candidiasis:e3/recall/1"},"12k0ot2":{"a":"recall","vg":"parasito-candidiasis:e3/recall/2"},"71nkdp":{"a":"recall","vg":"parasito-candidiasis:e4/recall/1"},"qtc8rh":{"a":"recall","vg":"parasito-candidiasis:e5/recall/1"},"1ay4gth":{"a":"recall","vg":"parasito-candidiasis:e6/recall/2"},"wzwp7f":{"a":"recall","vg":"parasito-candidiasis:e7/recall/1"},"1fb8zhd":{"a":"recall","vg":"parasito-candidiasis:e8/recall/1"},"87p32q":{"a":"recall","vg":"parasito-candidiasis:e9/recall/1"},"1ofkfcy":{"a":"recall","vg":"parasito-candidiasis:e10/recall/1"},"128u2ja":{"a":"recall","vg":"parasito-candidiasis:e11/recall/1"},"jdq83m":{"a":"recall","vg":"parasito-candidiasis:e11/recall/2"}},"explRev":"b32276695029"};
